package com.circle.oog;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
class ImportDetectionServiceTest {
    private void sheet(XSSFWorkbook wb,String name,String...headers){var s=wb.createSheet(name);var r=s.createRow(2);for(int i=0;i<headers.length;i++)r.createCell(i).setCellValue(headers[i]);var d=s.createRow(3);String[] v={"CASE1","2000","1000","1200","600"};for(int i=0;i<v.length;i++)d.createCell(i).setCellValue(v[i]);}
    @SuppressWarnings("unchecked") private Map<String,Object> first(Map<String,Object> result){return ((List<Map<String,Object>>)result.get("candidates")).get(0);}
    @Test void explicitHeadersYieldUniqueCandidateWithoutSwallowingData()throws Exception{try(var wb=new XSSFWorkbook()){sheet(wb,"Cargo","Item No","Length (mm)","Width (mm)","Height (mm)","Gross Weight per piece (kg)");var result=new ImportDetectionService().detect(wb);assertThat(result.get("autoSelectable")).isEqualTo(true);assertThat(first(result)).containsEntry("header",2).containsEntry("headerRows",1).containsEntry("lengthUnit","mm").containsEntry("weightUnit","kg").containsEntry("weightBasis","PER_PIECE");}}
    @Test void valuesNeverEstablishUnitsOrWeightBasis()throws Exception{try(var wb=new XSSFWorkbook()){sheet(wb,"Cargo","Item No","Length","Width","Height","Gross Weight");var candidate=first(new ImportDetectionService().detect(wb));assertThat(candidate.get("lengthUnit")).isNull();assertThat(candidate.get("weightUnit")).isNull();assertThat(candidate.get("weightBasis")).isNull();assertThat(candidate.get("requiresConfirmation")).isEqualTo(true);}}
    @Test void competingSheetsDoNotAutoSelect()throws Exception{try(var wb=new XSSFWorkbook()){for(String name:List.of("A","B"))sheet(wb,name,"Item No","Length","Width","Height","Gross Weight");var result=new ImportDetectionService().detect(wb);assertThat(result.get("autoSelectable")).isEqualTo(false);assertThat(result.get("recommendedCandidateId")).isNull();}}
    @Test void mixedUnitsRemainUnconfirmed()throws Exception{try(var wb=new XSSFWorkbook()){sheet(wb,"Cargo","Item No","Length (m)","Width (cm)","Height (mm)","Gross Weight row total (ton)");var c=first(new ImportDetectionService().detect(wb));assertThat(c.get("lengthUnit")).isNull();assertThat(c).containsEntry("weightUnit","ton").containsEntry("weightBasis","ROW_TOTAL");}}
    @Test void partialOrEmptyFileNeverAutoSelects()throws Exception{try(var wb=new XSSFWorkbook()){wb.createSheet("Empty");sheet(wb,"Partial","Item No","Length","Width","not height","unknown");assertThat(new ImportDetectionService().detect(wb).get("autoSelectable")).isEqualTo(false);}}
    @Test void mergedTwoRowPackedHeadersDetected()throws Exception{try(var wb=new XSSFWorkbook()){var s=wb.createSheet("Packed");var top=s.createRow(0);String[] titles={"Item No","Box Dimension(mm)","","","Gross Weight per piece(kg)"};for(int i=0;i<titles.length;i++)top.createCell(i).setCellValue(titles[i]);s.addMergedRegion(new org.apache.poi.ss.util.CellRangeAddress(0,0,1,3));var bottom=s.createRow(1);String[] children={"","Length","Width","Height",""};for(int i=0;i<children.length;i++)bottom.createCell(i).setCellValue(children[i]);var data=s.createRow(2);String[] values={"CASE1","2000","1000","1200","600"};for(int i=0;i<values.length;i++)data.createCell(i).setCellValue(values[i]);var r=new ImportDetectionService().detect(wb);assertThat(r.get("autoSelectable")).isEqualTo(true);assertThat(first(r)).containsEntry("headerRows",2).containsEntry("lengthUnit","mm");}}
}
